package br.com.dio.ui.custom.screen;import br.com.dio.Modelo.Space;import br.com.dio.service.BoardService;import br.com.dio.ui.custom.CheckGameStatusButton;import br.com.dio.ui.custom.FinishGameButton;import br.com.dio.ui.custom.ResetButton;import br.com.dio.ui.custom.frame.MainFrame;import br.com.dio.ui.custom.input.NumberText;import br.com.dio.ui.custom.panel.MainPanel;import br.com.dio.ui.custom.panel.SudokuSect;import javax.swing.*;import java.awt.*;import java.util.ArrayList;import java.util.List;import java.util.Map;import static javax.swing.JOptionPane.QUESTION_MESSAGE;import static javax.swing.JOptionPane.YES_NO_OPTION;public class MainScreen {    private final static Dimension dimension = new Dimension(600,600);    private final BoardService boardService;    private JButton checkGameStatusButton;    private JButton finishGameButton;    private JButton resetButton;    public MainScreen(final Map<String,String> gameConfig) {        this.boardService = new BoardService(gameConfig);    }    public void buildMainScreen(){        JPanel mainPanel = new MainPanel(dimension);        JFrame mainFrame = new MainFrame(dimension,mainPanel);        for(int r = 0; r < 9; r+=3){            var endRow = r+2;            for(int c = 0; c < 9; c+=3){                var endCol = c+2;                var spaces = getSpacesFromSector(boardService.getSpace(),c,endCol,r,endRow);                JPanel sector = genereteSection(spaces);                mainPanel.add(sector);            }        }        addResetButton(mainPanel);        addCheckGameStatusButton(mainPanel);        addFinishgameButton(mainPanel);        mainFrame.revalidate();        mainFrame.repaint();    }    private List<Space> getSpacesFromSector(final List<List<Space>> spaces, final int initCol, final int endCol, final int initRow, final int endRow){        List<Space> spaceSector = new ArrayList<>();        for(int r =  initRow; r<endRow; r++){            for(int c =  initCol; c<= endCol; c++){                spaceSector.add(spaces.get(c).get(r));            }        }        return spaceSector;    }    private JPanel genereteSection(final List<Space> spaces){        List<NumberText> fields = new ArrayList<>(spaces.stream().map(NumberText::new).toList());        return new SudokuSect(fields);    }    private void addFinishgameButton(final JPanel mainPanel) {        finishGameButton = new FinishGameButton(e ->{            if(boardService.gameIsFinished()){                JOptionPane.showMessageDialog(null,"Parabens voce conclui o jogo");                resetButton.setEnabled(false);                checkGameStatusButton.setEnabled(false);                finishGameButton.setEnabled(false);            } else{                var message = "seu jogo tem alguma inconsistencia, ajuste e tente novamente";                JOptionPane.showMessageDialog(null,message);            }        });        mainPanel.add(finishGameButton);    }    private void addCheckGameStatusButton(final JPanel mainPanel) {        checkGameStatusButton = new CheckGameStatusButton(e ->{            var hasErrors = boardService.hasErrors();            var gameStaus = boardService.getStatus();            var message = switch (gameStaus){                case NO_STARTING -> "O Jogo não foi iniciado!";                case INCOMPLETE ->  "O Jogo está imcompleto";                case COMPLETE ->  "O Jogo está completo";            };            message += hasErrors ? " e contem erros": "e não contem erros";            JOptionPane.showMessageDialog(null,message);        });        mainPanel.add(checkGameStatusButton);    }    private void addResetButton(final JPanel mainPanel) {        resetButton = new ResetButton(e->{            int dialogResult = JOptionPane.showConfirmDialog(null,                    "Deseja realmente reniciar o jogo?", "Limpar o joog",YES_NO_OPTION,QUESTION_MESSAGE);            if(dialogResult == 0){                boardService.reset();            }        });        mainPanel.add(resetButton);    }}